using sv_ca02bc033e494d1abd938bffd2eff457.Client.Services;

namespace sv_ca02bc033e494d1abd938bffd2eff457.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with fake data.
/// </summary>
public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 14, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "New York, NY", new DateTimeOffset(2026, 6, 8, 9, 0, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("Picked Up", "New York, NY", new DateTimeOffset(2026, 6, 9, 8, 30, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("In Transit", "Chicago, IL", new DateTimeOffset(2026, 6, 10, 14, 15, 0, TimeSpan.FromHours(-5))),
            ]),
        ["PKG-002"] = new Shipment(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 9, 12, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "Seattle, WA", new DateTimeOffset(2026, 6, 5, 10, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("Shipped", "Seattle, WA", new DateTimeOffset(2026, 6, 6, 7, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("In Transit", "Portland, OR", new DateTimeOffset(2026, 6, 7, 16, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("Out for Delivery", "San Francisco, CA", new DateTimeOffset(2026, 6, 9, 8, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 6, 9, 11, 42, 0, TimeSpan.FromHours(-7))),
            ]),
        ["PKG-003"] = new Shipment(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 18, 15, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "Dallas, TX", new DateTimeOffset(2026, 6, 10, 0, 30, 0, TimeSpan.FromHours(-5))),
            ]),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_ca02bc033e494d1abd938bffd2eff457.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment @TrackingNumber&hellip;</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>Shipment <strong>@TrackingNumber</strong> was not found.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Tracking History</h3>
        <table>
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Status</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates)
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Status</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;
    private string? _lastLoadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
