public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 14, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "New York, NY", new DateTimeOffset(2026, 6, 8, 9, 0, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("Picked Up", "New York, NY", new DateTimeOffset(2026, 6, 9, 8, 30, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("In Transit", "Chicago, IL", new DateTimeOffset(2026, 6, 10, 14, 15, 0, TimeSpan.FromHours(-5))),
            ]),
        ["PKG-002"] = new Shipment(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 9, 12, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "Seattle, WA", new DateTimeOffset(2026, 6, 5, 10, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("Shipped", "Seattle, WA", new DateTimeOffset(2026, 6, 6, 7, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("In Transit", "Portland, OR", new DateTimeOffset(2026, 6, 7, 16, 0, 0, TimeSpan.FromHours(-7))),
