                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 6, 9, 11, 42, 0, TimeSpan.FromHours(-7))),
            ]),
        ["PKG-003"] = new Shipment(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 18, 15, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "Dallas, TX", new DateTimeOffset(2026, 6, 10, 0, 30, 0, TimeSpan.FromHours(-5))),
            ]),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

